import{z as o,x as s,o as A,c as d,q as t,j as r,D as E,d as n,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"机器学习与因果的深化","description":"","frontmatter":{"title":"机器学习与因果的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pm-ml-causal-deep.md","filePath":"econ/pm-ml-causal-deep.md","lastUpdated":1791063341000}'),m={name:"econ/pm-ml-causal-deep.md"};function p(u,a,c,h,C,D){const l=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=t('<h1 id="机器学习与因果的深化" tabindex="-1">机器学习与因果的深化 <a class="header-anchor" href="#机器学习与因果的深化" aria-label="Permalink to &quot;机器学习与因果的深化&quot;">​</a></h1><div class="epigraph"><p>预测器再准也不回答反事实；「预测政策问题」的价值在于承认这一点之后，把只需要预测的决策从效应估计的整套装置里解放出来。</p><footer>—— 据 Kleinberg, Ludwig, Mullainathan and Obermeyer, Prediction Policy Problems, AER 2015；Athey and Imbens, Annual Review of Economics 2019 整理</footer></div><p><a href="/econ/pm-regularized-econ">上一课</a>把正则化的推断线收在双选择与去偏上。缺口从「估计系数」升级到「回答反事实」。主干课<a href="/econ/ml-causal-econ">机器学习与因果</a>已经钉过底线：ML 只估讨厌函数，不创造外生性；正交加交叉拟合把 ATE 拉回 \\(\\sqrt n\\) 推断；事后挑选控制会低估标准误。本课深钻因果侧的地图：预测问题与因果参数的分工、异质效应的估计器族、以及从效应到政策的最后一跳。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>四个参数常被「机器学习」一个词盖住：\\(E[y\\mid x]\\)（预测）、\\(E[y(1)-y(0)]\\)（平均效应）、\\(\\tau(x)\\)（异质效应）、\\(\\pi(x)\\)（最优分配规则）。目标不同，损失、验证标签、可检验性全部不同。最常见的错位是拿预测精度替效应估计背书：特征对 \\(y\\) 有预测力，不等于对效应有调节力。Kleinberg 等 2015 把这条边界正面用起来：当决策只需要预测不需要效应（谁会缺席听证、谁会再入院），预测器直接上线，绕开效应估计的整套装置；而「培训该分给谁」才需要 \\(\\tau(x)\\)，必须过识别设计。</p><p><span class="marginnote">术语翻译：ATE（平均处理效应）问「所有人平均多赚多少」；\\(\\tau(x)\\) 问「具体到某一类人多赚多少」。前者像全国平均降雨量，后者像分区降雨量——按全国平均数给每个区配防洪预算，就是拿 ATE 冒充 \\(\\tau(x)\\)，干旱区白白分到钱，洪涝区反而不够。</span></p><h3 id="元学习器与诚实分裂" tabindex="-1">元学习器与诚实分裂 <a class="header-anchor" href="#元学习器与诚实分裂" aria-label="Permalink to &quot;元学习器与诚实分裂&quot;">​</a></h3><p>异质效应没有直接标签——\\(y(1)\\) 与 \\(y(0)\\) 只见其一——只能间接构造：S-学习器把处理当特征放进一个模型；T-学习器分组建模再相减；X-学习器（Künzel 等 2019）用两组各自的补全差再加权，样本不均衡时更稳；DR-学习器把双重稳健得分当伪结果回归，留到下一课。因果树（Athey–Imbens 2016）的关键是诚实分裂：一半样本定叶子的划分，另一半估叶子内的效应——选择与估计分开，标准误才有理论；森林化（Wager–Athey 2018）补渐近正态与区间。政策学习是最后一跳：Kitagawa–Tetenov 2018 在受约束的政策类里最大化经验福利，回答的不是「效应多大」而是「按 \\(x\\) 分配的最优规则是什么」，评估靠福利损失界，不靠系数显著性。</p><p><span class="marginnote">直觉类比：诚实分裂像先由裁判划定考题范围（一半样本），再由另一批老师阅卷评分（另一半样本）。出题的人不碰阅卷，评分就没有「迁就自己出的题」的嫌疑；全混在一起，模型会先照着数据噪声切好格子，再在格子里「验证」自己。</span></p><p><span class="marginnote">保释决定只需要「被告人若释放，弃保潜逃概率」的预测；再就业培训的分配才需要异质效应。两类问题被同一个词「预测」盖住时最危险：前者用预测精度验收，后者必须过识别——错拿前者做后者，是把风险评估当成因果承诺。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程五步固定。先写参数：四个里要哪个。再写识别：CIA 或 IV 从哪来，ML 不参与这一步。第三选估计器：异质用元学习器加诚实分裂，均值用下一课的 DML。第四选验证：预测参数用样本外；效应参数只能用代理——效应得分的校准、诚实分裂下的区间、有子实验时分域对照。第五做政策映射：声明政策类与约束（预算、公平性），报福利损失界而非系数表。每一跳都有交付物，跳不过去的环节停下来，而不是换个更花哨的模型。</p>',12)),(A(),r(i,null,{default:E(()=>[B(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%86%99%E5%8F%82%E6%95%B0%3A%20%E9%A2%84%E6%B5%8B%2FATE%2F%E5%BC%82%E8%B4%A8%2F%E6%94%BF%E7%AD%96%22%5D%20--%3E%20I%5B%22%E5%86%99%E8%AF%86%E5%88%AB%3A%20CIA%20%E6%88%96%20IV%22%5D%0A%20%20I%20--%3E%20E%5B%22%E9%80%89%E4%BC%B0%E8%AE%A1%E5%99%A8%3A%20%E5%85%83%E5%AD%A6%E4%B9%A0%E5%99%A8%E4%B8%8E%E8%AF%9A%E5%AE%9E%E5%88%86%E8%A3%82%22%5D%0A%20%20E%20--%3E%20V%7B%22%E5%8F%82%E6%95%B0%E7%B1%BB%E5%9E%8B%3F%22%7D%0A%20%20V%20--%3E%7C%22%E9%A2%84%E6%B5%8B%22%7C%20OOS%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E9%AA%8C%E8%AF%81%22%5D%0A%20%20V%20--%3E%7C%22%E6%95%88%E5%BA%94%22%7C%20PROXY%5B%22%E6%95%88%E5%BA%94%E5%BE%97%E5%88%86%E6%A0%A1%E5%87%86%E4%B8%8E%E5%88%86%E7%BB%84%22%5D%0A%20%20V%20--%3E%7C%22%E6%94%BF%E7%AD%96%22%7C%20WEL%5B%22%E6%94%BF%E7%AD%96%E7%B1%BB%E5%86%85%E7%BB%8F%E9%AA%8C%E7%A6%8F%E5%88%A9%22%5D%0A%20%20OOS%20--%3E%20OUT%5B%22%E6%8A%A5%E5%91%8A%E4%BA%A4%E4%BB%98%E7%89%A9%22%5D%0A%20%20PROXY%20--%3E%20OUT%0A%20%20WEL%20--%3E%20OUT%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"诚实分裂为什么救推断：树的过拟合来自「用同一份数据既找划分又估效应」，分裂之后另一半数据面对固定的划分做估计，经典中心极限定理适用，叶子效应的置信区间有出处。预测与效应的错位为什么普遍：两者的监督信号不同——一个对 \\(y\\)，一个对只可见一方的伪效应——能分出 \\(y\\) 的特征自然不需要能调节 \\(\\tau(x)\\)，反之亦然。政策学习的机制是把决策问题的损失显式化：福利损失界直接惩罚「把好配置分错」的规则，估计误差与优化误差分开记账。",-1)),a[5]||(a[5]=e("p",null,"诚实分裂把一份样本拆成两个角色，推断的合法性由此而来：",-1)),(A(),r(i,null,{default:E(()=>[B(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%85%A8%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20H%5B%22%E4%B8%80%E5%8D%8A%E6%A0%B7%E6%9C%AC%20A%EF%BC%9A%E5%8F%AA%E5%86%B3%E5%AE%9A%E6%A0%91%E7%9A%84%E5%88%92%E5%88%86%22%5D%0A%20%20D%20--%3E%20G%5B%22%E5%8F%A6%E4%B8%80%E5%8D%8A%E6%A0%B7%E6%9C%AC%20B%EF%BC%9A%E5%9C%A8%E5%9B%BA%E5%AE%9A%E5%88%92%E5%88%86%E5%86%85%E4%BC%B0%E6%95%88%E5%BA%94%22%5D%0A%20%20H%20--%3E%20F%5B%22%E5%8F%B6%E5%AD%90%E5%BD%A2%E7%8A%B6%E5%86%BB%E7%BB%93%EF%BC%8C%E4%B8%8D%E5%86%8D%E6%94%B9%22%5D%0A%20%20G%20--%3E%20E%5B%22%E5%8F%B6%E5%86%85%E4%BC%B0%E8%AE%A1%E6%97%A0%E9%80%89%E6%8B%A9%E5%81%8F%E5%B7%AE%22%5D%0A%20%20F%20--%3E%20CI%5B%22%E7%BB%8F%E5%85%B8%20CLT%20%E9%80%82%E7%94%A8%EF%BC%9A%E7%BD%AE%E4%BF%A1%E5%8C%BA%E9%97%B4%E6%9C%89%E7%90%86%E8%AE%BA%22%5D%0A%20%20E%20--%3E%20CI%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：特征对结局 \\(y\\) 预测力强，不等于对效应 \\(\\tau(x)\\) 有调节力。「既往病史多」能预测医疗支出高，但未必意味着某项治疗对这类人更见效——「谁会花很多钱」与「谁更受益」是两个问题，验收标准必须分开：前者用样本外精度，后者只能靠校准与分组对照。</span></p><p>不这么做会错在哪：拿整体 ATE 分配资源（掩盖异质）；拿叶子的显著名单当政策规则（没有福利记账）；拿预测指标验收效应模型（错位验收）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>识别不因算法改变：CIA、IV、不重叠的假设清单照旧，算法只改变讨厌函数的填充质量。元学习器的相对优劣依讨厌函数收敛率与两组样本配比，没有全胜者。\\(\\tau(x)\\) 的逐点验证不可行——反事实不可观测——只能校准与分组，「异质效应被验证了」的说法要拆开看。文本作为特殊的 \\(x\\) 与 \\(y\\) 是另一条通道，接后面两课；均值效应的正交得分装置正是下一课的地盘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四个参数四种损失：预测、ATE、异质效应、政策规则；目标错配是最贵的错误。</li><li>异质效应靠元学习器间接构造；诚实分裂把选择与估计分开，推断才有理论。</li><li>预测准不背书效应准；只需要预测的决策应直接用预测器，不必假装估效应。</li><li>政策学习在受约束的政策类内最大化经验福利，评估靠福利损失界。</li><li>出处：Kleinberg, Ludwig, Mullainathan and Obermeyer, <em>AER</em> 2015；Athey and Imbens, <em>PNAS</em> 2016；Wager and Athey, <em>JASA</em> 2018；Künzel, Sekhon, Bickel and Yu, <em>PNAS</em> 2019；Kitagawa and Tetenov, <em>Econometrica</em> 2018；Mullainathan and Spiess, <em>JEP</em> 2017。</li></ul>',6))])}const b=o(m,[["render",p]]);export{F as __pageData,b as default};
